using Xunit;

namespace Warp.JsCompiler.Tests;

/// <summary>
/// Small, independently serialized class-super cases.  These deliberately do
/// not reuse the larger language-suite class fixture: a mismatch identifies
/// the precise receiver and property-access form that regressed.
/// </summary>
public sealed class ClassSuperGoldenTests
{
    [Fact]
    public void Instance_method_calls_inherited_method()
        => GoldenAssert.Module(
            "class B { f() { return 1; } } class D extends B { h() { return super.f(); } }",
            "/tmp/super-instance.js",
            "");

    [Fact]
    public void Static_method_calls_computed_inherited_method()
        => GoldenAssert.Module(
            "class B { static f() { return 1; } } class D extends B { static h() { return super[\"f\"](); } }",
            "/tmp/super-static.js",
            "");
}
